head.script:

    scwin.onpageload = function() {
		window.log_last = [];

		var jsonData = [{col1:"a",col2:"a1",col3:"false", col4:"true"}
						,{col1:"a",col2:"a2",col3:"false", col4:"true"}
						,{col1:"a",col2:"a3",col3:"false", col4:"true"}
						,{col1:"a",col2:"a4",col3:"false", col4:"true"}
						,{col1:"a",col2:"a5",col3:"false", col4:"true"}
						,{col1:"b",col2:"b1",col3:"false", col4:"true"}
						,{col1:"b",col2:"b3",col3:"false", col4:"true"}
						,{col1:"c",col2:"c1",col3:"false", col4:"true"}
						,{col1:"c",col2:"c2",col3:"false", col4:"true"}
						,{col1:"c",col2:"c3",col3:"false", col4:"true"}
						,{col1:"d",col2:"d1",col3:"false", col4:"true"}
						,{col1:"d",col2:"d2",col3:"false", col4:"true"}
						,{col1:"d",col2:"d3",col3:"false", col4:"true"}];
		dataList1.setJSON(jsonData);

    };

    scwin.onpageunload = function() {

    };
    	scwin.dataList1_oncelldatachange = function(info){
			console.log("dataList1_oncelldatachange");
			window.log_last.push('dataList1_oncelldatachange');
    	}

		scwin.gridView1_oncellclick = function(rowIdx, colIdx, colID){
			if(colID == "col3" || colID == "col4"){
				console.log("gridView1_oncellclick");
				window.log_last.push('gridView1_oncellclick');
			}
		}

	scwin.dbClick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}

	scwin.checkArrayOrder = function(arr) {
		const expectedOrder = ['dataList1_oncelldatachange', 'gridView1_oncellclick'];
		let isCorrect = arr.length === expectedOrder.length;

		debugger;
		arr.forEach((value, index) => {
			if (value !== expectedOrder[index]) {
				isCorrect = false;
			}
		});

		return isCorrect;
	}

	scwin.checkVal1 = function() {
		scwin.checkArrayOrder(window.log_last);
		return scwin.checkArrayOrder(window.log_last);
	}		
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_2').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.dbClick('gridView1_cell_0_2')");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1__col2').value = '11'");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_4').children[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest(); 
	localStorage.removeItem("log");
